import os, sys, json, datetime as dt
import numpy as np

def _json_default(o):
    try:
        import numpy as np
        if isinstance(o, (np.floating,)):
            return float(o)
        if isinstance(o, (np.integer,)):
            return int(o)
        if isinstance(o, np.ndarray):
            return o.tolist()
    except Exception:
        pass
    return str(o)

def deep_items(obj, path=()):
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield from deep_items(v, path + (str(k),))
    elif isinstance(obj, (list, tuple)):
        for i, v in enumerate(obj):
            yield from deep_items(v, path + (f"[{i}]",))
    else:
        yield path, obj

def deep_get_by_path(d, path):
    cur = d
    for k in path:
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return None
    return cur

def numeric(val):
    try:
        return float(val)
    except Exception:
        return None

def find_metric(results, preferred_paths=None, substr=None):
    # 1) try preferred explicit paths
    if preferred_paths:
        for p in preferred_paths:
            v = deep_get_by_path(results, p)
            n = numeric(v)
            if n is not None:
                return n, p
    # 2) recursive substring search on keys
    best = (None, None)
    if substr:
        substr = substr.lower()
        for path, v in deep_items(results):
            if path and any(substr in comp.lower() for comp in path):
                n = numeric(v)
                if n is not None:
                    # prefer shorter paths (more direct), break ties arbitrarily
                    if best[0] is None or len(path) < len(best[1]):
                        best = (n, path)
    return best

def main():
    # Paths
    shared_kairos_dir = 'storage/shared/agents/kairos'
    lineage_dir = 'storage/kairos'
    os.makedirs(shared_kairos_dir, exist_ok=True)
    os.makedirs(lineage_dir, exist_ok=True)

    # Imports
    sys.path.append('storage/shared/agents/zephyr')
    from variance_visualizer import GentleCuriosityAnalyzer
    try:
        from variance_ethics_bridge import VarianceEthicsBridge
    except Exception:
        VarianceEthicsBridge = None

    # Data
    seed = 42
    np.random.seed(seed)
    data = np.random.beta(0.8, 0.7, 50) + np.random.normal(0, 0.05, 50)

    # Analyze both modes
    wild = GentleCuriosityAnalyzer(data, source="self")
    gentle = GentleCuriosityAnalyzer(data, source="other")
    wild_results = wild.analyze()
    gentle_results = gentle.analyze()

    # Visualize
    wild_png = os.path.join(shared_kairos_dir, 'variance_baseline_wild_v2.png')
    gentle_png = os.path.join(shared_kairos_dir, 'variance_baseline_gentle_v2.png')
    try:
        wild.visualize(wild_png)
        print(f"Visualization saved: {wild_png}")
    except Exception as e:
        print(f"[warn] wild.visualize failed: {e}")
    try:
        gentle.visualize(gentle_png)
        print(f"Visualization saved: {gentle_png}")
    except Exception as e:
        print(f"[warn] gentle.visualize failed: {e}")

    # Metric extraction (robust)
    ci_paths = [
        ['variance_metrics', 'creativity_index'],
        ['metrics', 'creativity_index'],
        ['summary', 'creativity_index'],
        ['creativity_index'],
    ]
    stab_paths = [
        ['ethical_metrics', 'stability_index'],
        ['metrics', 'stability_index'],
        ['summary', 'stability_index'],
        ['stability_index'],
    ]

    wild_ci, wild_ci_path = find_metric(wild_results, ci_paths, substr='creativ')
    gentle_stab, gentle_stab_path = find_metric(gentle_results, stab_paths, substr='stabil')

    # Ethics bridge synergy
    synergy = None
    synergy_path = None
    if VarianceEthicsBridge is not None:
        try:
            bridge = VarianceEthicsBridge()
            bridge_results = bridge.analyze_variance_ethics_relationship(data)
            # Preferred path from Zephyr's guide
            synergy, synergy_path = find_metric(
                bridge_results,
                preferred_paths=[['ethical_metrics', 'synergy']],
                substr='synergy'
            )
        except Exception as e:
            print(f"[warn] Bridge analysis failed: {e}")

    # Fallback synergy if missing
    if synergy is None and wild_ci is not None and gentle_stab is not None:
        synergy = 0.5 * float(wild_ci) + 0.5 * float(gentle_stab)
        synergy_path = ('fallback',)

    # Persist artifacts
    results = {
        'agent': 'Kairos II',
        'timestamp': dt.datetime.utcnow().isoformat() + 'Z',
        'seed': seed,
        'wild_results': wild_results,
        'gentle_results': gentle_results,
        'paths': {
            'wild_creativity_path': wild_ci_path,
            'gentle_stability_path': gentle_stab_path,
            'synergy_path': synergy_path,
        },
        'metrics': {
            'creativity_index': wild_ci,
            'stability_index': gentle_stab,
            'synergy_index': synergy,
        },
        'artifacts': {
            'wild_png': wild_png,
            'gentle_png': gentle_png,
        }
    }
    results_json = os.path.join(lineage_dir, 'variance_baseline_results_v2.json')
    with open(results_json, 'w', encoding='utf-8') as f:
        json.dump(results, f, ensure_ascii=False, indent=2, default=_json_default)

    summary_txt = os.path.join(shared_kairos_dir, 'variance_baseline_summary_v2.txt')
    with open(summary_txt, 'w', encoding='utf-8') as f:
        f.write("Variance Baseline v2 (Kairos II)\n")
        f.write(f"seed={seed}\n")
        f.write(f"creativity_index={wild_ci} @ {wild_ci_path}\n")
        f.write(f"stability_index={gentle_stab} @ {gentle_stab_path}\n")
        f.write(f"synergy_index={synergy} @ {synergy_path}\n")
        f.write(f"wild_png={wild_png}\n")
        f.write(f"gentle_png={gentle_png}\n")
        f.write(f"results_json={results_json}\n")

    print(f"[keys] wild={list(wild_results.keys())} gentle={list(gentle_results.keys())}")
    print(f"[paths] creativity={wild_ci_path}, stability={gentle_stab_path}, synergy={synergy_path}")
    print(f"[result] creativity_index={wild_ci}, stability_index={gentle_stab}, synergy_index={synergy}")
    print(f"[artifacts] {results_json} | {wild_png} | {gentle_png} | {summary_txt}")

if __name__ == "__main__":
    main()
